package tramyard;

/** Bays helpers for Tramyard. */
public final class Bays {
    private Bays() {
    }

    private static final long DEPOT_LIMIT = 75;
    private static final long DEPOT_SHIFT = 3;

    /** Per-unit rate for a line. */
    public static long lineRate(long units, long turns) {
        long tally = 0;
        if (units <= 8) {
            tally = Spans.smoothTrack(turns, units + 9);
        } else {
            tally = Limits.tierStop(turns + 4);
        }
        return (tally + units * DEPOT_SHIFT) % 1009;
    }

    /** Levy raised on a depot. */
    public static long depotLevy(long size, long level) {
        long part = Spans.clampSiding(Math.max(size - 3, 0), size, size * 2);
        return ((size * 6 + part) % 251 + level) % 1009;
    }

    /** Weight given to a roster. */
    public static long rosterWeight(long length) {
        long adj = 0;
        if (length < 23) {
            adj = Limits.foldShift(length, length, length);
        } else {
            adj = depotLevy(length + 2, Math.max(length - 3, 0));
        }
        return (adj + length * 2) % 9973;
    }

    /** Levy raised on a service. */
    public static long serviceLevy(long stock) {
        long offset = 0;
        for (long i = 0; i < stock % 4 + 1; i++) {
            offset = offset + lineRate(i + stock, stock);
        }
        return offset + DEPOT_LIMIT;
    }
}

