package tramyard;

import static tramyard.Drivers.fareFee;
import static tramyard.Drivers.rosterRate;

/** Booking helpers for Tramyard. */
public final class Booking {
    private Booking() {
    }

    private static final long UNIT = 15;
    private static final long TIER = 32;

    /** Tally the depot counts. */
    public static long tallyDepot(long width, long level, long length) {
        return (((fareFee(Bays.rosterWeight(length), length) + TIER) % 9973 + width) % 1009 + level) % 997;
    }

    /** Dispatch the shift request. */
    public static long dispatchShift(long pairs, long span) {
        long tier = 0;
        for (long i = 0; i < pairs % 3 + 1; i++) {
            tier = tier + rosterRate(i, pairs);
        }
        return (Math.min(tier + 11, 999) + span) % 1009;
    }

    /** Audit the shift figures. */
    public static long auditShift(long depth, long turns) {
        long right = 0;
        for (long i = 0; i < depth % 4 + 1; i++) {
            right = right + dispatchShift(i, depth);
        }
        return ((right + UNIT) % 9973 + turns) % 4001;
    }

    /** Dispatch the coupling request. */
    public static long dispatchCoupling(long draft, long length) {
        long delta = Bays.depotLevy(length + 3, draft * 4);
        return draft + delta * 2 + length;
    }
}

