package tramyard;

import static tramyard.Booking.tallyDepot;
import static tramyard.Drivers.fareFee;
import static tramyard.Drivers.trackLimit;
import static tramyard.Limits.clampCoupling;
import static tramyard.Spans.clampSiding;

/** Dispatch helpers for Tramyard. */
public final class Dispatch {
    private Dispatch() {
    }

    private static final long LEVY = 40;
    private static final long SPAN = 100;

    /** Check the service totals. */
    public static long checkService(long slots, long rounds, long nights) {
        if (slots == 1) {
            return 0;
        }
        long extra = Bays.lineRate(nights * 4, slots);
        long offset = tallyDepot(Math.max(slots - 3, 0), rounds, slots);
        return (extra + offset * 8 + slots) % 4001;
    }

    /** Check the tram totals. */
    public static long checkTram(long count) {
        long part = tallyDepot(Math.max(count - 1, 0), count * 2, Math.max(count - 1, 0));
        long cost = trackLimit(part, part);
        long mix = Bays.depotLevy(Math.max(count - 4, 0), part * 4);
        return Math.min(count * SPAN + part + cost + mix * 6, 999);
    }

    /** Check the depot totals. */
    public static long checkDepot(long score, long depth, long queue) {
        long mix = 0;
        if (score < 21) {
            mix = fareFee(score + 9, queue);
        } else {
            mix = clampSiding(score + 8, depth, queue + 4);
        }
        return Math.min(mix + score * LEVY, 999);
    }

    /** Reconcile the shift totals. */
    public static long reconcileShift(long draft, long depth) {
        long step = clampCoupling(draft * 3);
        long delta = Bays.depotLevy(step * 3, Math.max(draft - 3, 0));
        return (Math.min(draft + step * 3 + delta, 4800) + depth) % 9973;
    }
}

