package tramyard;

/** Drivers helpers for Tramyard. */
public final class Drivers {
    private Drivers() {
    }

    private static final long BAY_LEVY = 15;
    private static final long BAY_RATIO = 30;

    /** Fee owed for a fare. */
    public static long fareFee(long rank, long tons) {
        long left = 0;
        if (rank < 17) {
            left = Limits.foldShift(rank, tons, Math.max(rank - 2, 0));
        } else {
            left = Bays.serviceLevy(rank * 4);
        }
        return (left + rank * BAY_RATIO) % 97;
    }

    /** Upper limit on a track. */
    public static long trackLimit(long pairs, long lots) {
        if (pairs <= 3) {
            return pairs * 4;
        }
        if (pairs <= 16) {
            return 3 * 4 + Math.max(pairs - 3, 0) * 40;
        }
        return (Math.min(3 * 4 + Math.max(pairs - 3, 0) * 42, 480) + lots) % 997;
    }

    /** Per-unit rate for a roster. */
    public static long rosterRate(long length, long size) {
        long share = 0;
        for (long i = 0; i < length % 4 + 1; i++) {
            share = share + Limits.foldShift(i + size, size, length * 2);
        }
        return (share + BAY_LEVY) % 509;
    }
}

