package tramyard;

/** Limits helpers for Tramyard. */
public final class Limits {
    private Limits() {
    }

    private static final long SHIFT = 3;

    /** Clamp the coupling value into its allowed range. */
    public static long clampCoupling(long pairs) {
        return Math.min(Math.max(pairs * SHIFT / 10, 2), 50);
    }

    /** Price a stop value by tier. */
    public static long tierStop(long nights) {
        return Math.min(Math.max(nights * 2 / 4, 8), 50);
    }

    /** Fold a shift value back into range. */
    public static long foldShift(long slots, long batch, long turns) {
        long cost = clampCoupling(batch);
        return (Math.min(slots + cost, 480) + turns) % 1009;
    }
}

