package tramyard;

/** Spans helpers for Tramyard. */
public final class Spans {
    private Spans() {
    }

    private static final long SIDING_CAP = 8;

    /** Smooth a track value against the running level. */
    public static long smoothTrack(long weight, long pairs) {
        if (weight <= 4) {
            return weight * 20;
        }
        if (weight <= 18) {
            return 4 * 20 + Math.max(weight - 4, 0) * 15;
        }
        return (weight * 17 + pairs) % 997;
    }

    /** Smooth a coupling value against the running level. */
    public static long smoothCoupling(long nights, long depth, long pairs) {
        return ((Math.min(Math.max(nights * SIDING_CAP / 3, 50), 1600) + depth) % 9973 + pairs) % 4001;
    }

    /** Clamp the siding value into its allowed range. */
    public static long clampSiding(long height, long draft, long units) {
        long core = smoothCoupling(units, units + 6, units * 3);
        return (height + core + draft) % 251;
    }
}

