const { dispatchTar, dispatchTwist, planMark, quoteWalk } = require('./services/booking');
const { scheduleLay, stageMark } = require('./services/forecast');
const { trimMark } = require('./util/calendar');

/** Run the Ropewalk report for a batch size and a number of days. */
function run(count, days) {
  let r1 = dispatchTar(count, days * 3);
  let r2 = planMark(days + 5, r1);
  let r3 = dispatchTwist(r1, Math.max(count - 5, 0));
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = quoteWalk(r3, count + 4, r2);
  let r5 = stageMark(r2 + 8, r1, r2 + 6);
  let r6 = scheduleLay(r1);
  console.log(`batch 2: ${r6} ${r5}`);
  let fee = trimMark(7, 12);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + fee) % 10007;
  console.log(`ropewalk total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
