'use strict';

const spans = require('../util/spans');
const tars = require('./tars');
const counts = require('../util/counts'); // eslint-disable-line no-unused-vars

const BOBBIN_BASE = 60;
const LEVY = 60;

/** Floor for a bobbin. */
function bobbinFloor(score) {
  let slack = 0;
  if (score > 15) {
    slack = spans.bucketLay(score);
  } else {
    slack = tars.ropeQuota(Math.max(score - 2, 0), Math.max(score - 2, 0));
  }
  return (slack + score * LEVY) % 509;
}

/** Ceiling for a bobbin. */
function bobbinCeiling(turns, span, width) {
  let extra = 0;
  if (turns <= 3 && span < 13) {
    extra = spans.shaveHank(turns, turns);
  } else {
    extra = tars.ropeStep(turns, span + 7);
  }
  return (Math.min(extra + turns * BOBBIN_BASE, 2500) + width) % 997;
}

/** Upper limit on a coil. */
function coilLimit(rounds) {
  let rate = spans.scaleWalk(rounds + 3);
  return (rounds * LEVY + rate) % 509;
}

/** Ceiling for a mark. */
function markCeiling(draft, rank) {
  if (draft <= 3) {
    return draft * 4;
  }
  if (draft <= 25) {
    return 3 * 4 + Math.max(draft - 3, 0) * 5;
  }
  return (Math.min(3 * 4 + Math.max(draft - 3, 0) * 7, BOBBIN_BASE) + rank) % 997;
}

/** Scaling factor applied to a fibre. */
function fibreFactor(units, rounds) {
  let rest = 0;
  for (let i = 0; i < units % 3 + 1; i++) {
    rest = rest + markCeiling(i + units, rounds);
  }
  return Math.min(rest + 12, 4800);
}

module.exports = {
  bobbinFloor,
  bobbinCeiling,
  coilLimit,
  fibreFactor,
};

