const fathoms = require('./fathoms');
const { padReel, roundTwist } = require('../util/counts');
const spans = require('../util/spans');
const { capMark } = require('../util/calendar');
const tars = require('./tars'); // eslint-disable-line no-unused-vars

const WALK_BASE = 30;
const WALK_SLOPE = 50;

/** Scaling factor applied to a fathom. */
function fathomFactor(level, weight) {
  let share = fathoms.bobbinCeiling(weight, level * 4, level);
  let delta = roundTwist(weight + 8, weight);
  let extra = fathoms.bobbinFloor(level);
  return (level + share + delta * 2 + extra * 2) % 509;
}

/** Levy raised on a walk. */
function walkLevy(level) {
  let slack = spans.shaveFathom(level);
  return (level * 3 + slack * 4) % 97;
}

/** Step size for a mark. */
function markStep(queue) {
  return (padReel(capMark(queue * 4, queue), queue) + WALK_BASE) % 1009;
}

/** Scaling factor applied to a bobbin. */
function bobbinFactor(hours, score) {
  let adj = spans.bucketLay(score);
  return Math.min(hours + adj * WALK_BASE, 9000);
}

/** Upper limit on a lay. */
function layLimit(length, draft, height) {
  let extra = markStep(height);
  let delta = fathomFactor(height, extra * 2);
  let carry = fathoms.coilLimit(Math.max(extra - 1, 0));
  return (length + extra * 3 + delta + carry * WALK_SLOPE + draft * 5) % 4001;
}

module.exports = {
  walkLevy,
  markStep,
  bobbinFactor,
  layLimit,
};

