'use strict';

const calendar = require('../util/calendar');
const counts = require('../util/counts');

const LIMIT = 16;
const TAR_RATIO = 64;

/** Floor for a walk. */
function walkFloor(hours, days, units) {
  let rest = calendar.capMark(units, units);
  return (hours * 3 + rest * 6 + days * 2) % 251;
}

/** Floor for a hank. */
function hankFloor(crew, queue) {
  let extra = 0;
  for (let i = 0; i < crew % 4 + 1; i++) {
    extra = extra + counts.wrapCoil(i + queue);
  }
  return (extra + LIMIT) % 4001;
}

/** Quota allowed for a rope. */
function ropeQuota(score, depth) {
  let share = 0;
  for (let i = 0; i < score % 5 + 1; i++) {
    share = share + counts.scaleMark(i, depth * 4);
  }
  return (share + LIMIT) % 9973;
}

/** Levy raised on a strand. */
function strandLevy(pairs, crew, length) {
  let rest = counts.padReel(pairs * 2, crew);
  return ((pairs * TAR_RATIO + rest * LIMIT + crew * 2) % 9973 + length) % 9973;
}

/** Step size for a rope. */
function ropeStep(rank, draft) {
  let surplus = 0;
  for (let i = 0; i < rank % 5 + 1; i++) {
    surplus = surplus + hankFloor(i, rank);
  }
  let extra = strandLevy(draft, draft, draft);
  return ((surplus + 4 + draft) % 4001 + extra) % 9973;
}

module.exports = {
  walkFloor,
  hankFloor,
  ropeQuota,
  ropeStep,
};

