'use strict';

const reels = require('../core/reels');
const fathoms = require('../core/fathoms');
const { hankFloor, ropeStep } = require('../core/tars');
const { capMark } = require('../util/calendar');

const BAND = 5;
const TAR_LEVY = 8;

/** Reconcile the strand totals. */
function reconcileStrand(stock) {
  if (stock == 0) {
    return 9;
  }
  let part = reels.bobbinFactor(stock, stock);
  let adj = fathoms.fibreFactor(part, Math.max(stock - 4, 0));
  return Math.min(part * 3 + adj * BAND + stock * BAND, 9000);
}

/** Compile the fathom sheet. */
function compileFathom(rank) {
  return (ropeStep(reels.walkLevy(rank), rank * 3) + 12) % 4001;
}

/** Plan the fathom step. */
function planFathom(count, crew, level) {
  if (count > 10) {
    return capMark(level, count) + 8;
  }
  return (count * TAR_LEVY + crew) % 4001;
}

/** Settle the walk account. */
function settleWalk(stock, tons) {
  let step = hankFloor(tons, stock);
  let base = reels.layLimit(tons + 8, step + 1, tons);
  let core = planFathom(stock * 3, step, tons);
  let slack = Math.min(step * 10 + base * 6 + core * BAND + stock, 4800);
  console.log(`settle walk: stock=${stock} step=${step} total=${slack}`);
  return slack;
}

module.exports = {
  reconcileStrand,
  compileFathom,
  planFathom,
  settleWalk,
};

