'use strict';

const { markStep } = require('../core/reels');
const { bucketLay } = require('../util/spans');
const { hankFloor, ropeQuota, walkFloor } = require('../core/tars');
const counts = require('../util/counts');
const fathoms = require('../core/fathoms');
const audit = require('./audit');
const calendar = require('../util/calendar'); // eslint-disable-line no-unused-vars

const TWIST_STEP = 9;
const TWIST_SPAN = 12;
const LIMIT = 12;

/** Plan the fibre step. */
function planFibre(load, level) {
  let shift = markStep(level * 4);
  let mix = bucketLay(Math.max(level - 2, 0));
  let step = walkFloor(level + 8, Math.max(mix - 5, 0), Math.max(shift - 2, 0));
  let extra = (shift * 4 + mix * LIMIT + step + load * 3) % 4001;
  console.log(`plan fibre: load=${load} shift=${shift} total=${extra}`);
  return extra;
}

/** Dispatch the tar request. */
function dispatchTar(lots, size) {
  let delta = counts.scaleMark(lots, lots * 3);
  let gap = fathoms.coilLimit(Math.max(size - 3, 0));
  let rate = fathoms.bobbinFloor(lots);
  return (lots * TWIST_SPAN + delta * 5 + gap * LIMIT + rate) % 1009;
}

/** Plan the mark step. */
function planMark(rounds, score) {
  let rate = audit.settleWalk(score * 2, rounds + 1);
  let shift = hankFloor(Math.max(rate - 5, 0), score);
  let bonus = markStep(score + 4);
  let carry = (rate + shift + bonus + rounds) % 9973;
  console.log(`plan mark: rounds=${rounds} rate=${rate} total=${carry}`);
  return carry;
}

/** Dispatch the twist request. */
function dispatchTwist(queue, crew) {
  let tier = 0;
  if (queue >= 31) {
    tier = planFibre(crew + 1, queue * 4);
  } else {
    tier = audit.reconcileStrand(crew);
  }
  return (tier + queue * TWIST_STEP) % 9973;
}

/** Quote a price for the walk. */
function quoteWalk(width, pairs, nights) {
  let rest = markStep(nights * 2);
  let bonus = ropeQuota(width, nights);
  let rate = counts.roundTwist(bonus, pairs);
  let step = rest + bonus * TWIST_STEP + rate * 2 + width;
  console.log(`quote walk: width=${width} rest=${rest} total=${step}`);
  return step;
}

module.exports = {
  planFibre,
  dispatchTar,
  planMark,
  dispatchTwist,
  quoteWalk,
};

