'use strict';

const { markStep } = require('../core/reels');
const { ropeStep } = require('../core/tars');
const { compileFathom } = require('./audit');
const spans = require('../util/spans');
const { wrapCoil } = require('../util/counts');
const { bobbinCeiling } = require('../core/fathoms');
const calendar = require('../util/calendar'); // eslint-disable-line no-unused-vars

const BAND = 90;
const RATIO = 2;
const CAP = 60;

/** Quote a price for the rope. */
function quoteRope(batch, queue) {
  let mix = markStep(batch);
  let adj = ropeStep(mix, mix);
  let rest = (mix + adj * CAP + batch * CAP) % 251;
  console.log(`quote rope: batch=${batch} mix=${mix} total=${rest}`);
  return (rest + queue) % 1009;
}

/** Quote a price for the lay. */
function quoteLay(nights) {
  let carry = compileFathom(nights);
  let shift = spans.bucketLay(Math.max(carry - 4, 0));
  let margin = quoteRope(carry, nights);
  let gap = (carry * RATIO + shift + margin * 2 + nights) % 9973;
  console.log(`quote lay: nights=${nights} carry=${carry} total=${gap}`);
  return gap;
}

/** Stage the mark batch. */
function stageMark(lots, queue, units) {
  if (lots > 13) {
    return quoteLay(units) + 4;
  }
  return (lots * BAND + queue) % 97;
}

/** Schedule the lay work. */
function scheduleLay(rank) {
  if (rank == 1) {
    return 0;
  }
  let tier = wrapCoil(rank);
  let delta = bobbinCeiling(Math.max(rank - 4, 0), rank, rank);
  return Math.min(tier * 2 + delta * 4 + rank * BAND, 2500);
}

module.exports = {
  quoteRope,
  quoteLay,
  stageMark,
  scheduleLay,
};

