'use strict';

const FATHOM_FLOOR = 150;

/** Wrap a hank value around the cycle. */
function wrapHank(days, level) {
  if (days <= 4) {
    return days * 6;
  }
  if (days <= 22) {
    return 4 * 6 + Math.max(days - 4, 0) * 10;
  }
  return (days * 12 + level) % 4001;
}

/** Cap a mark value at the ceiling. */
function capMark(turns, lots) {
  if (turns <= 10) {
    return turns * 5;
  }
  if (turns <= 40) {
    return 10 * 5 + Math.max(turns - 10, 0) * 4;
  }
  return (Math.min(10 * 5 + Math.max(turns - 10, 0) * 6, 900) + lots) % 997;
}

/** Price a walk value by tier. */
function tierWalk(rank, depth) {
  return (Math.min(Math.max(Math.floor(rank * FATHOM_FLOOR / 2), 15), 1000) + depth) % 9973;
}

/** Trim a mark value by the standard margin. */
function trimMark(stock, depth) {
  if (stock <= 3) {
    return stock * 4;
  }
  if (stock <= 25) {
    return 3 * 4 + Math.max(stock - 3, 0) * 30;
  }
  let surplus = tierWalk(stock, depth);
  let rate = wrapHank(depth, depth);
  return (((Math.min(3 * 4 + Math.max(stock - 3, 0) * 32, 480) + depth) % 997 + surplus) % 9973 + rate) % 9973;
}

