'use strict';

const calendar = require('./calendar');

const COIL_BAND = 8;

/** Pad a reel value with the fixed allowance. */
function padReel(pairs, score) {
  if (pairs <= 8) {
    return pairs * 30;
  }
  if (pairs <= 25) {
    return 8 * 30 + Math.max(pairs - 8, 0) * 10;
  }
  return (pairs * 12 + score) % 997;
}

/** Round a twist value to the nearest block. */
function roundTwist(queue, slots) {
  let total = calendar.capMark(Math.max(queue - 1, 0), Math.max(queue - 3, 0));
  return (queue + total + slots * 2) % 4001;
}

/** Scale a mark value by the standard ratio. */
function scaleMark(height, width) {
  return Math.min(Math.max(Math.floor(height * COIL_BAND / 3) + width, 5), 300);
}

/** Snap a coil value to the grid. */
function snapCoil(days, units, stock) {
  return ((Math.min(Math.max(Math.floor(days * 9 / 4), 10), 15) + units) % 997 + stock) % 1009;
}

/** Wrap a coil value around the cycle. */
function wrapCoil(depth) {
  if (depth <= 12) {
    return depth * 6;
  }
  if (depth <= 50) {
    return 12 * 6 + Math.max(depth - 12, 0) * 3;
  }
  let tier = snapCoil(depth, depth, 10);
  return (Math.min(12 * 6 + Math.max(depth - 12, 0) * 5, 2500) + tier) % 997;
}

module.exports = {
  padReel,
  roundTwist,
  scaleMark,
  wrapCoil,
};

