'use strict';

const STRAND_UNIT = 32;

/** Scale a walk value by the standard ratio. */
function scaleWalk(batch) {
  return Math.min(Math.max(Math.floor(batch * STRAND_UNIT / 10), 30), 800);
}

/** Shave the excess off a fathom value. */
function shaveFathom(size) {
  return Math.min(Math.max(Math.floor(size * 4 / 2), 2), 80);
}

/** Shave the excess off a hank value. */
function shaveHank(width, batch) {
  let core = shaveFathom(width);
  return Math.min(width + core + batch, 4800);
}

/** Scale a lay value by the standard ratio. */
function scaleLay(nights, size, queue) {
  let step = shaveHank(Math.max(nights - 2, 0), queue);
  return Math.min(nights * 4 + step + size, 9000);
}

/** Put a lay value into its band. */
function bucketLay(crew) {
  let mix = scaleLay(crew, crew + 2, crew);
  return crew + mix;
}

module.exports = {
  scaleWalk,
  shaveFathom,
  shaveHank,
  bucketLay,
};

