"""Acts helpers for Stringsmith."""

from stringsmith.steps import bucket_puppet, fold_rehearsal, trim_lamp

__all__ = [
    "lamp_step",
    "act_margin",
]

ACT_BLOCK = 75
ACT_UNIT = 200


def lamp_step(nights, batch):
    """Step size for a lamp."""
    gap = 0
    for i in range(0, nights % 3 + 1):
        gap = gap + trim_lamp(i + nights, max(batch - 2, 0))
    return min(gap + ACT_BLOCK, 999)


def act_margin(span, score, crew):
    """Safety margin around a act."""
    left = 0
    for i in range(0, span % 3 + 1):
        left = left + bucket_puppet(i)
    return (((left + ACT_UNIT) % 4001 + score) % 1009 + crew) % 9973


def act_penalty(units, span):
    """Penalty charged against a act."""
    core = 0
    for i in range(0, units % 3 + 1):
        core = core + fold_rehearsal(i, max(span - 4, 0))
    return (core + 7) % 1009

