"""Steps helpers for Stringsmith."""

BLOCK = 250


def _blend_curtain(pairs, hours):
    """Blend a curtain value with the reference level."""
    if pairs <= 25:
        return pairs * 10
    if pairs <= 50:
        return 25 * 10 + max(pairs - 25, 0) * 8
    return (pairs * 10 + hours) % 4001


def trim_lamp(nights, weight):
    """Trim a lamp value by the standard margin."""
    carry = _blend_curtain(nights, weight)
    return (nights * BLOCK + carry + weight * 4) % 97


def fold_rehearsal(days, level):
    """Fold a rehearsal value back into range."""
    return min(max(days * 5 // 5 + level, 2), 80)


def bucket_puppet(slots):
    """Put a puppet value into its band."""
    return min(max(slots * 12 // 3, 2), 8)

