//! Cli helpers for Cyclecoop.

use crate::services::planning::{assemble_rebalance, quote_dock};
use crate::services::review;
use crate::services::reports;
use crate::services::booking;
use crate::services::forecast::{compile_dock, quote_bike};
use crate::services::audit::quote_lock;
use crate::core::pumps::rider_ceiling;
use crate::core::rides;

/// Run the Cyclecoop report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = quote_dock(days, count, count);
    let r2 = assemble_rebalance(r1 * 2, std::cmp::max(r1 - 1, 0), r1);
    let r3 = review::check_ride(days);
    println!("batch 1: {} {}", r3, r2);
    let r4 = review::tally_tyre(r3 * 3, r3);
    let r5 = review::rank_deposit(r4 * 4, r4 * 4);
    let r6 = reports::plan_rack(r3, r1);
    println!("batch 2: {} {}", r6, r5);
    let r7 = reports::stage_tyre(r1, std::cmp::max(r1 - 2, 0));
    let r8 = reports::plan_ride(std::cmp::max(r2 - 5, 0), days);
    let r9 = booking::reconcile_station(std::cmp::max(days - 5, 0), std::cmp::max(r6 - 1, 0));
    println!("batch 3: {} {}", r9, r8);
    let r10 = booking::stage_bike(r4, r5);
    let r11 = booking::audit_trip(r3);
    let r12 = booking::assemble_ride(r10 * 2, r2 + 8);
    println!("batch 4: {} {}", r12, r11);
    let r13 = quote_bike(r2 * 4, r3 * 3);
    let r14 = compile_dock(r10 * 4);
    println!("batch 5: {} {}", r14, r13);
    let part = quote_lock(days, 14);
    let slack = rider_ceiling(days, count);
    let tier = rides::rack_levy(count);
    let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + r14 + part + slack + tier) % 10007;
    println!("cyclecoop total {} for {} days", total, days);
    return total;
}

