//! Bells helpers for Cyclecoop.

use crate::util::ratios::round_ride;
use crate::util::limits::scale_pump;
use crate::core::trips::deposit_share;
use crate::core::rides;

const SLOPE: i64 = 90;
const PUMP_BAND: i64 = 16;

/// Floor for a rebalance.
pub fn rebalance_floor(count: i64, size: i64, width: i64) -> i64 {
    let mut rate = 0;
    for i in 0..count % 4 + 1 {
        rate = rate + round_ride(i);
    }
    return ((rate + PUMP_BAND + size) % 997 + width) % 1009;
}

/// Weight given to a dock.
pub fn dock_weight(draft: i64) -> i64 {
    if draft <= 4 {
        return draft * 15;
    }
    if draft <= 40 {
        return 4 * 15 + std::cmp::max(draft - 4, 0) * 6;
    }
    return std::cmp::min(4 * 15 + std::cmp::max(draft - 4, 0) * 8, SLOPE);
}

/// Score of a bell.
pub fn bell_score(slots: i64, load: i64) -> i64 {
    let mut rest = 0;
    if slots > 7 && load > 12 {
        rest = scale_pump(slots + 4);
    } else {
        rest = deposit_share(slots + 2, slots);
    }
    return std::cmp::min(rest + slots * SLOPE, 4800);
}

/// Bonus granted for a trip.
pub fn trip_bonus(tons: i64, turns: i64, slots: i64) -> i64 {
    if tons == 1 {
        return 0;
    }
    let bonus = rides::ride_score(turns + 9, turns + 3, tons);
    let surplus = rebalance_floor(slots + 2, tons * 2, turns);
    return (bonus * 3 + surplus + tons) % 97;
}

