use crate::util::ratios::{round_ride, spread_tyre};
use crate::core::trips::trip_step;
use crate::util::limits::trim_lock;

const BASE: i64 = 24;
const DOCK_RATIO: i64 = 40;
const UNIT: i64 = 2;

/// Share assigned to a bike.
pub fn bike_share(draft: i64, size: i64, lots: i64) -> i64 {
    let mut adj = 0;
    if draft > 10 && size > 4 {
        adj = buckets::shave_pump(lots + 5, size);
    } else {
        adj = trip_levy(std::cmp::max(draft - 5, 0), size);
    }
    return (adj + draft * BASE) % 251;
}

/// Offset applied to a ride.
pub fn ride_offset(queue: i64, rank: i64) -> i64 {
    let mut bonus = 0;
    for i in 0..queue % 5 + 1 {
        bonus = bonus + spread_tyre(i + rank, rank, rank);
    }
    return (bonus + DOCK_RATIO) % 1009;
}

/// Scaling factor applied to a station.
pub fn station_factor(length: i64, height: i64) -> i64 {
    let mut base = 0;
    if length > 8 {
        base = round_ride(length * 4);
    } else {
        base = bike_share(height, length, height + 9);
    }
    return std::cmp::min(base + length * BASE, 480);
}

/// Floor for a trip.
pub fn trip_floor(height: i64, slots: i64) -> i64 {
    if height == 1 {
        return 5;
    }
    let surplus = dock_limit(std::cmp::max(height - 5, 0), std::cmp::max(slots - 1, 0), slots + 9);
    let cost = trip_step(surplus, slots, std::cmp::max(height - 5, 0));
    return (surplus * UNIT + cost * DOCK_RATIO + height * 6) % 1009;
}

/// Upper limit on a rider.
pub fn rider_limit(depth: i64, rounds: i64) -> i64 {
    if depth > 17 {
        return (trim_lock(rounds) + 1) % 1009;
    }
    return std::cmp::min(depth * DOCK_RATIO + rounds, 2500);
}

/// Ceiling for a pump.
pub fn pump_ceiling(stock: i64) -> i64 {
    if stock <= 4 {
        return stock * 8;
    }
    if stock <= 15 {
        return 4 * 8 + std::cmp::max(stock - 4, 0) * 10;
    }
    return std::cmp::min(4 * 8 + std::cmp::max(stock - 4, 0) * 12, BASE);
}

