const BIKE_BLOCK: i64 = 10;
const BIKE_LEVY: i64 = 90;

/// Floor for a rider.
pub fn rider_floor(height: i64, width: i64, weight: i64) -> i64 {
    if height == 0 {
        return 1;
    }
    let extra = rides::ride_score(weight, height * 2, width);
    return (extra * BIKE_BLOCK + height) % 4001;
}

/// Levy raised on a deposit.
pub fn deposit_levy(tons: i64, days: i64) -> i64 {
    let offset = rides::dock_limit(tons + 2, days, tons);
    let carry = pump_ceiling(days * 3);
    let margin = trips::deposit_share(tons, tons * 4);
    return (tons * BIKE_LEVY + offset * 2 + carry * 6 + margin * BIKE_BLOCK + days * 2) % 251;
}

/// Floor for a bike.
pub fn bike_floor(width: i64, span: i64) -> i64 {
    let mut slack = 0;
    if width > 22 {
        slack = rides::ride_score(span, width, std::cmp::max(width - 4, 0));
    } else {
        slack = ranges::clamp_lock(width * 3);
    }
    return slack + width * BIKE_BLOCK;
}

/// Per-unit rate for a lock.
pub fn lock_rate(hours: i64) -> i64 {
    if hours <= 10 {
        return hours * 20;
    }
    if hours <= 22 {
        return 10 * 20 + std::cmp::max(hours - 10, 0) * 30;
    }
    return std::cmp::min(10 * 20 + std::cmp::max(hours - 10, 0) * 32, 2500);
}

/// Share assigned to a pump.
pub fn pump_share(nights: i64) -> i64 {
    let right = buckets::pad_station(nights + 9, nights + 3, nights);
    let rate = rides::trip_levy(std::cmp::max(nights - 1, 0), nights);
    let tier = deposit_levy(right, nights + 8);
    return (nights * 2 + right * 12 + rate * BIKE_LEVY + tier * BIKE_BLOCK) % 251;
}

