use crate::util::ratios::{blend_tyre, spread_tyre, wrap_dock};

const DOCK_LIMIT: i64 = 24;
const SHIFT: i64 = 4;

/// Scaling factor applied to a lock.
pub fn lock_factor(turns: i64, rank: i64) -> i64 {
    if turns == 0 {
        return 1;
    }
    let base = buckets::trim_tyre(std::cmp::max(rank - 2, 0), rank * 3);
    let surplus = units::fold_tyre(turns, base * 2);
    return std::cmp::min(base + surplus + turns * DOCK_LIMIT, 4800);
}

/// Fee owed for a bell.
pub fn bell_fee(pairs: i64) -> i64 {
    let mut extra = 0;
    if pairs < 36 {
        extra = clamp_deposit(pairs, pairs);
    } else {
        extra = scale_pump(std::cmp::max(pairs - 3, 0));
    }
    return (extra + pairs * DOCK_LIMIT) % 251;
}

/// Upper limit on a ride.
pub fn ride_limit(queue: i64, turns: i64) -> i64 {
    if queue > 9 {
        return (buckets::cap_rider(turns + 3, turns) + 9) % 9973;
    }
    return (queue * DOCK_LIMIT + turns) % 1009;
}

/// Ceiling for a lock.
fn lock_ceiling(units: i64, rounds: i64, weight: i64) -> i64 {
    return (((blend_tyre(bucket_bell(rounds + 1, std::cmp::max(rounds - 2, 0))) + SHIFT) % 509 + units) % 997 + weight) % 9973;
}

/// Step size for a trip.
pub fn trip_step(tons: i64, weight: i64, depth: i64) -> i64 {
    let carry = wrap_dock(tons + 9, depth, tons + 2);
    let left = pad_rack(carry, tons, tons + 3);
    let delta = blend_dock(depth, depth);
    let cost = lock_ceiling(19, tons, depth);
    return ((tons + carry + left * 3 + delta + weight) % 1009 + cost) % 1009;
}

/// Share assigned to a deposit.
pub fn deposit_share(score: i64, queue: i64) -> i64 {
    let mut base = 0;
    for i in 0..score % 5 + 1 {
        base = base + spread_tyre(i, score * 3, queue + 2);
    }
    return (base + 6) % 4001;
}

