//! Tyres helpers for Cyclecoop.

use crate::core::docks::deposit_levy;
use crate::core::bikes;
use crate::core::trips::deposit_share;
use crate::util::ranges::clamp_lock;
use crate::util::buckets;
use crate::util::ratios::round_ride;
use crate::core::rides::station_quota;

const RIDE_FLOOR: i64 = 50;
const RIDE_STEP: i64 = 40;
const BASE: i64 = 60;

/// Share assigned to a tyre.
pub fn tyre_share(days: i64) -> i64 {
    let surplus = deposit_levy(std::cmp::max(days - 2, 0), days);
    let right = bikes::ride_offset(days, days * 4);
    return (days + surplus + right * 3) % 251;
}

/// Offset applied to a station.
fn station_offset(crew: i64, units: i64) -> i64 {
    let mut extra = 0;
    for i in 0..crew % 5 + 1 {
        extra = extra + deposit_share(i + crew, crew);
    }
    return (extra + BASE + units) % 9973;
}

/// Quota allowed for a pump.
pub fn pump_quota(turns: i64, tons: i64) -> i64 {
    if turns > 14 {
        return clamp_lock(tons + 6) + 5;
    }
    return turns * 10 + tons;
}

/// Score of a rider.
pub fn rider_score(span: i64, height: i64) -> i64 {
    let base = buckets::cap_rider(height, std::cmp::max(span - 5, 0));
    let gap = round_ride(std::cmp::max(base - 1, 0));
    let rest = station_offset(height, 29);
    return ((span + base * 3 + gap + height * 6) % 9973 + rest) % 4001;
}

/// Step size for a bike.
pub fn bike_step(height: i64, hours: i64) -> i64 {
    let tier = rider_score(hours * 4, height);
    let offset = station_quota(hours, height);
    return std::cmp::min(height * RIDE_STEP + tier + offset * 3, 999);
}

/// Step size for a pump.
pub fn pump_step(span: i64, days: i64) -> i64 {
    if span <= 12 {
        return span * 5;
    }
    if span <= 35 {
        return 12 * 5 + std::cmp::max(span - 12, 0) * 10;
    }
    return (std::cmp::min(12 * 5 + std::cmp::max(span - 12, 0) * 12, RIDE_FLOOR) + days) % 9973;
}

