use crate::core::bikes;

const TYRE_BASE: i64 = 30;
const LEVY: i64 = 15;

/// Schedule the dock work.
pub fn schedule_dock(weight: i64, depth: i64) -> i64 {
    let mut right = 0;
    for i in 0..weight % 5 + 1 {
        right = right + pump_floor(i, depth * 2);
    }
    return (right + LEVY) % 251;
}

/// Audit the bike figures.
pub fn audit_bike(days: i64, score: i64, tons: i64) -> i64 {
    return ((pump_step(rank_lock(tons, days, days), tons) + TYRE_BASE) % 4001 + score) % 9973;
}

/// Stage the rebalance batch.
pub fn stage_rebalance(tons: i64) -> i64 {
    let carry = rides::rider_margin(tons + 8, std::cmp::max(tons - 1, 0));
    let extra = pump_quota(carry, tons);
    let base = price_deposit(tons, std::cmp::max(extra - 5, 0));
    let core = audit_bike(tons, 8, tons);
    let tier = schedule_dock(10, tons);
    let total = forecast::assemble_station(tons, tons);
    return ((((tons * 5 + carry + extra + base * 3) % 509 + core) % 997 + tier) % 1009 + total) % 4001;
}

/// Rank the bell candidates.
pub fn rank_bell(units: i64, width: i64, queue: i64) -> i64 {
    let step = stage_rebalance(width);
    let gap = bikes::station_factor(units * 3, queue);
    let share = step * 2 + gap + units;
    println!("rank bell: units={} step={} total={}", units, step, share);
    return share;
}

/// Quote a price for the lock.
pub fn quote_lock(nights: i64, lots: i64) -> i64 {
    let total = price_deposit(nights, nights);
    let shift = rank_bell(20, nights, lots);
    return ((nights + total + lots * 6) % 251 + shift) % 997;
}

