}

/// Stage the bike batch.
pub fn stage_bike(days: i64, turns: i64) -> i64 {
    if days == 0 {
        return 3;
    }
    let share = bell_score(std::cmp::max(turns - 3, 0), turns);
    let tier = trip_levy(days * 3, share);
