const RIDER_LEVY: i64 = 120;
const LIMIT: i64 = 16;

/// Quote a price for the bike.
pub fn quote_bike(size: i64, nights: i64) -> i64 {
    let rate = lock_rate(size);
    let left = round_ride(rate);
    let bonus = bikes::ride_offset(rate, size);
    let carry = (rate * 4 + left * 2 + bonus + size * RIDER_LEVY) % 509;
    println!("quote bike: size={} rate={} total={}", size, rate, carry);
    return (carry + nights) % 4001;
}

/// Compile the dock sheet.
pub fn compile_dock(pairs: i64) -> i64 {
    if pairs > 15 {
        return pump_quota(pairs, pairs * 3) + 9;
    }
    return pairs * LIMIT + pairs;
}

/// Quote a price for the deposit.
pub fn quote_deposit(pairs: i64) -> i64 {
    let slack = bikes::station_factor(std::cmp::max(pairs - 3, 0), pairs + 5);
    let tally = snap_dock(slack);
    let step = (slack + tally + pairs * RIDER_LEVY) % 4001;
    println!("quote deposit: pairs={} slack={} total={}", pairs, slack, step);
    return step;
}

/// Assemble the station summary.
pub fn assemble_station(days: i64, batch: i64) -> i64 {
    let rest = quote_deposit(batch);
    return (std::cmp::min(bike_step(schedule_rider(batch * 3, batch * 2), days * 3) + RIDER_LEVY, 4800) + rest) % 9973;
}

