const UNIT: i64 = 7;
const SHIFT: i64 = 60;

/// Quote a price for the dock.
pub fn quote_dock(nights: i64, rounds: i64, load: i64) -> i64 {
    return ((dock_weight(bike_step(nights, load)) + SHIFT) % 4001 + rounds) % 997;
}

/// Rank the rebalance candidates.
pub fn rank_rebalance(slots: i64, rounds: i64) -> i64 {
    if slots == 0 {
        return 8;
    }
    let extra = rack_quota(rounds + 3);
    return extra * 6 + slots * 6;
}

/// Schedule the rider work.
pub fn schedule_rider(stock: i64, width: i64) -> i64 {
    return (bell_score(rack_score(stock, std::cmp::max(stock - 2, 0)), width) + SHIFT) % 9973;
}

/// Dispatch the lock request.
pub fn dispatch_lock(span: i64) -> i64 {
    let shift = units::fold_tyre(span, span);
    let offset = ride_factor(shift + 3);
    let total = tyre_share(span * 4);
    let mix = (shift + offset * 4 + total + span * 12) % 1009;
    println!("dispatch lock: span={} shift={} total={}", span, shift, mix);
    return mix;
}

/// Assemble the rebalance summary.
pub fn assemble_rebalance(queue: i64, span: i64, draft: i64) -> i64 {
    let surplus = ride_factor(draft);
    let left = trips::lock_factor(surplus, surplus);
    let core = surplus * UNIT + left * SHIFT + queue;
    println!("assemble rebalance: queue={} surplus={} total={}", queue, surplus, core);
    return (core + span) % 4001;
}

