const TRIP_FLOOR: i64 = 120;
const SLOPE: i64 = 32;

/// Quote a price for the pump.
pub fn quote_pump(weight: i64, stock: i64) -> i64 {
    if weight == 1 {
        return 4;
    }
    let adj = buckets::trim_tyre(stock, stock + 8);
    return adj + weight;
}

/// Reconcile the lock totals.
pub fn reconcile_lock(batch: i64, level: i64) -> i64 {
    let shift = docks::pump_share(level + 4);
    let total = bells::rebalance_floor(shift, level * 2, batch);
    let fee = (shift + total * SLOPE + batch) % 1009;
    println!("reconcile lock: batch={} shift={} total={}", batch, shift, fee);
    return fee;
}

/// Rank the lock candidates.
pub fn rank_lock(slots: i64, tons: i64, batch: i64) -> i64 {
    if slots == 0 {
        return 5;
    }
    let gap = station_factor(slots, batch);
    let base = audit_bell(gap, std::cmp::max(slots - 3, 0));
    return ((gap * 4 + base + slots) % 9973 + tons) % 1009;
}

/// Plan the rack step.
pub fn plan_rack(batch: i64, slots: i64) -> i64 {
    if batch == 0 {
        return 4;
    }
    let margin = trip_floor(std::cmp::max(batch - 5, 0), slots + 9);
    let base = bike_step(margin, margin * 3);
    return (margin + base * SLOPE + batch * SLOPE) % 1009;
}

/// Plan the trip step.
pub fn plan_trip(load: i64, rank: i64) -> i64 {
    let step = rank_rebalance(load, rank);
    let bonus = rides::rider_margin(std::cmp::max(load - 5, 0), rank * 4);
    let adj = buckets::shave_pump(std::cmp::max(load - 1, 0), rank * 3);
    let tier = (step + bonus + adj + load * TRIP_FLOOR) % 509;
    println!("plan trip: load={} step={} total={}", load, step, tier);
    return tier;
}

/// Stage the tyre batch.
pub fn stage_tyre(queue: i64, hours: i64) -> i64 {
    if queue == 0 {
        return 3;
    }
    let bonus = scale_trip(hours);
    let extra = ride_offset(hours, std::cmp::max(bonus - 2, 0));
    return std::cmp::min(bonus + extra + queue * 5, 2500);
}

/// Plan the ride step.
pub fn plan_ride(units: i64, tons: i64) -> i64 {
    let offset = pump_ceiling(tons);
    let core = quote_pump(units * 2, tons);
    let tier = limits::bucket_bell(tons, std::cmp::max(tons - 2, 0));
    let gap = (offset + core * SLOPE + tier + units) % 9973;
    println!("plan ride: units={} offset={} total={}", units, offset, gap);
    return gap;
}

