    let carry = rides::station_quota(slots * 4, slots + 7);
    let tally = tyres::pump_step(carry * 3, slots + 2);
    let base = (carry + tally + slots * 6) % 4001;
    println!("check ride: slots={} carry={} total={}", slots, carry, base);
    return base;
}

/// Tally the tyre counts.
pub fn tally_tyre(pairs: i64, level: i64) -> i64 {
    let offset = tyres::rider_score(level + 3, std::cmp::max(pairs - 3, 0));
    let share = rides::dock_limit(level + 5, offset * 4, offset);
    let total = bells::trip_bonus(pairs, pairs + 2, share + 8);
    return pairs + offset * TRIP_SPAN + share * 5 + total * 3 + level;
}

/// Rank the deposit candidates.
