    let delta = fold_tyre(units + 4, std::cmp::max(units - 5, 0));
    let mix = pump_floor(units + 8, delta + 3);
    let step = buckets::smooth_dock(delta, delta + 5);
    let shift = (delta * TRIP_FLOOR + mix * 3 + step + units) % 9973;
    println!("rank deposit: units={} delta={} total={}", units, delta, shift);
    return (shift + count) % 1009;
}

/// Audit the bell figures.
