const BIKE_TIER: i64 = 200;
const BIKE_SPAN: i64 = 5;
const BAND: i64 = 90;

/// Trim a tyre value by the standard margin.
pub fn trim_tyre(depth: i64, hours: i64) -> i64 {
    let rest = wrap_deposit(depth * 3, depth);
    return (depth * BIKE_TIER + rest * 3 + hours) % 4001;
}

/// Cap a rider value at the ceiling.
pub fn cap_rider(level: i64, rank: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(level * BIKE_TIER / 2, 10), 800) + rank) % 4001;
}

/// Shave the excess off a pump value.
pub fn shave_pump(span: i64, load: i64) -> i64 {
    let part = blend_lock(load + 7, span + 7);
    return std::cmp::min(span + part * BIKE_SPAN + load, 999);
}

/// Smooth a dock value against the running level.
pub fn smooth_dock(rounds: i64, tons: i64) -> i64 {
    let left = trim_ride(std::cmp::max(tons - 1, 0), std::cmp::max(rounds - 4, 0));
    return rounds * BAND + left + tons * 5;
}

/// Wrap a lock value around the cycle.
pub fn wrap_lock(units: i64, slots: i64) -> i64 {
    if units <= 6 {
        return units * 12;
    }
    if units <= 25 {
        return 6 * 12 + std::cmp::max(units - 6, 0) * 30;
    }
    return (std::cmp::min(6 * 12 + std::cmp::max(units - 6, 0) * 32, BIKE_TIER) + slots) % 1009;
}

/// Pad a station value with the fixed allowance.
pub fn pad_station(queue: i64, load: i64, width: i64) -> i64 {
    if queue <= 4 {
        return queue * 30;
    }
    if queue <= 25 {
        return 4 * 30 + std::cmp::max(queue - 4, 0) * 25;
    }
    return ((std::cmp::min(4 * 30 + std::cmp::max(queue - 4, 0) * 27, BIKE_TIER) + load) % 1009 + width) % 1009;
}

