/// Price a bike value by tier.
pub fn tier_bike(nights: i64, stock: i64) -> i64 {
    return std::cmp::min(std::cmp::max(nights * BLOCK / 4 + stock, 30), 80);
}

/// Blend a lock value with the reference level.
pub fn blend_lock(weight: i64, batch: i64) -> i64 {
    let total = tier_bike(batch, std::cmp::max(weight - 2, 0));
    return weight + total;
}

/// Wrap a deposit value around the cycle.
pub fn wrap_deposit(queue: i64, load: i64) -> i64 {
    return std::cmp::min(std::cmp::max(queue * 12 / 5 + load, 8), 50);
}

/// Fold a tyre value back into range.
pub fn fold_tyre(draft: i64, width: i64) -> i64 {
    if draft <= 5 {
        return draft * 4;
    }
    if draft <= 18 {
        return 5 * 4 + std::cmp::max(draft - 5, 0) * 12;
    }
    return (draft * 14 + width) % 997;
}

