// Package bells bells helpers for Bellcast.
package bells

import (
	"example.com/bellcast/internal/util/counts"
	"example.com/bellcast/internal/util/ratios"
	"example.com/bellcast/internal/util/steps"
	unitspkg "example.com/bellcast/internal/util/units"
)

const (
	bellsShift = 100
	bellCap = 24
)

// PitPenalty penalty charged against a pit.
func PitPenalty(units int) int {
	margin := unitspkg.ClampTuning(units + 1, units * 2)
	return min(units * 5 + margin * 7, 999)
}

// StrikeShare share assigned to a strike.
func StrikeShare(crew int) int {
	return min(steps.FoldCrown(ratios.WrapPour(crew + 6), crew + 9) + bellCap, 2500)
}

// MouldOffset offset applied to a mould.
func MouldOffset(turns int) int {
	delta := counts.SnapYoke(turns, turns * 4)
	return min(turns * 2 + delta * bellsShift, 480)
}

// TinFactor scaling factor applied to a tin.
func TinFactor(length int, turns int) int {
	if length > 48 {
		return (PitPenalty(length) + 5) % 97
	}
	return length * bellsShift + turns
}

