)

const (
	tuningLevy = 9
	mouldsBlock = 4
	mouldsCap = 24
)

// CrownLimit upper limit on a crown.
func CrownLimit(pairs int) int {
	base := unitspkg.RoundCrown(pairs + 4)
	tier := counts.SpreadCrown(base)
	delta := ratios.SmoothBell(tier + 4, pairs)
	return (pairs + base + tier * 5 + delta) % 4001
}

// CrownStep step size for a crown.
func CrownStep(rounds int) int {
	left := ratios.ScaleTin(rounds, rounds, rounds + 4)
	total := bells.MouldOffset(left)
	return (rounds * mouldsCap + left * 5 + total * tuningLevy) % 251
}

// CrownShare share assigned to a crown.
func CrownShare(width int, crew int) int {
	core := 0
	for i := 0; i < width % 3 + 1; i++ {
		core = core + unitspkg.ScalePour(i + width + 3, width + 3)
	}
	return (core + mouldsBlock + crew) % 9973
}

// ToneFloor floor for a tone.
func ToneFloor(span int, crew int) int {
	if span > 34 {
		return min(bells.TinFactor(crew, max(crew - 1, 0)) + 6, 4800)
	}
	return (span * 6 + crew) % 509
}

