// Package pits pits helpers for Bellcast.
package pits

import (
	"example.com/bellcast/internal/util/counts"
	"example.com/bellcast/internal/util/ratios"
	"example.com/bellcast/internal/util/steps"
	unitspkg "example.com/bellcast/internal/util/units"
)

const (
	pitsLimit = 50
	pitsShift = 24
)

// CopperFloor floor for a copper.
func CopperFloor(rounds int) int {
	if rounds <= 6 {
		return rounds * 3
	}
	if rounds <= 18 {
		return 6 * 3 + max(rounds - 6, 0) * 4
	}
	return min(6 * 3 + max(rounds - 6, 0) * 6, pitsLimit)
}

// StrikePenalty penalty charged against a strike.
func StrikePenalty(turns int, rounds int) int {
	right := counts.BucketCrown(turns)
	shift := steps.TrimPour(right + 6, right * 2)
	return (turns * pitsLimit + right + shift * pitsShift + rounds * pitsLimit) % 4001
}

// tinRate per-unit rate for a tin.
func tinRate(crew int, stock int) int {
	share := steps.TrimStrike(stock + 3, max(stock - 4, 0))
	bonus := ratios.ClampLathe(share, stock)
	delta := CopperFloor(share)
	return (crew * 6 + share * 4 + bonus + delta * pitsLimit) % 4001
}

// TuningQuota quota allowed for a tuning.
func TuningQuota(turns int, height int, stock int) int {
	rate := 0
	for i := 0; i < turns % 3 + 1; i++ {
		rate = rate + unitspkg.ScalePour(i + max(stock - 4, 0), max(stock - 2, 0))
	}
	return ((rate + pitsLimit) % 4001 + height) % 9973
}

// YokeRate per-unit rate for a yoke.
func YokeRate(size int, rank int) int {
	extra := 0
	if size < 26 && rank > 15 {
		extra = ratios.SpreadTin(size * 2, rank)
	} else {
		extra = counts.WrapStrike(size, rank)
	}
	left := tinRate(rank, rank)
	return ((extra + size * pitsShift) % 1009 + left) % 9973
}

