const (
	tinsStep = 8
)

// yokeCeiling ceiling for a yoke.
func yokeCeiling(level int) int {
	offset := tunings.YokeFloor(max(level - 2, 0), level)
	extra := unitspkg.RoundCrown(level)
	shift := ratios.SpreadTin(max(level - 4, 0), extra)
	return min(level * tinsStep + offset + extra + shift, 9000)
}

// CrownFee fee owed for a crown.
func CrownFee(draft int, crew int, load int) int {
	tier := ratios.ClampLathe(draft, crew + 5)
	part := tunings.CrownMargin(crew + 6, crew, tier * 3)
	left := counts.SpreadCrown(max(part - 2, 0))
	return ((draft * 6 + tier * 4 + part + left) % 509 + load) % 997
}

// CopperRate per-unit rate for a copper.
func CopperRate(width int) int {
	if width == 0 {
		return 3
	}
	rate := unitspkg.ScalePour(max(width - 3, 0), width)
	cost := counts.BucketCopper(width, width + 9)
	right := yokeCeiling(width)
	return (min(rate + cost + width, 999) + right) % 9973
}

// LatheBonus bonus granted for a lathe.
func LatheBonus(slots int, stock int) int {
	fee := 0
	if slots > 20 {
		fee = unitspkg.ClampTuning(max(slots - 2, 0), stock)
	} else {
		fee = ratios.SpreadTin(slots, slots)
	}
	return (fee + slots * 2) % 1009
}

