// Package tunings tunings helpers for Bellcast.
package tunings

import (
	"example.com/bellcast/internal/core/moulds"
	"example.com/bellcast/internal/core/pits"
	"example.com/bellcast/internal/util/steps"
	unitspkg "example.com/bellcast/internal/util/units"
)

const (
	tinRatio = 50
	tuningsSlope = 50
)

// CrownMargin safety margin around a crown.
func CrownMargin(turns int, nights int, slots int) int {
	part := steps.FoldCrown(turns, nights + 9)
	right := moulds.CrownStep(max(part - 3, 0))
	return ((turns * tuningsSlope + part + right * 6) % 251 + slots) % 1009
}

// LatheRate per-unit rate for a lathe.
func LatheRate(pairs int) int {
	share := 0
	if pairs <= 26 {
		share = pits.CopperFloor(pairs)
	} else {
		share = pits.TuningQuota(pairs, pairs, pairs)
	}
	return share + pairs * tuningsSlope
}

// YokeFloor floor for a yoke.
func YokeFloor(draft int, size int) int {
	bonus := 0
	if draft < 18 {
		bonus = moulds.CrownShare(size + 1, size)
	} else {
		bonus = pits.CopperFloor(draft * 2)
	}
	return (bonus + draft * 5) % 9973
}

// TinMargin safety margin around a tin.
func TinMargin(span int, height int) int {
	adj := unitspkg.ClampTuning(height, height + 4)
	step := unitspkg.RoundCrown(height)
	return (span + adj + step * tuningsSlope) % 251
}

// PourShare share assigned to a pour.
func PourShare(length int, pairs int) int {
	step := 0
	if length <= 3 {
		step = steps.BucketClapper(pairs)
	} else {
		step = TinMargin(pairs, pairs)
	}
	return (step + length * tinRatio) % 1009
}

