// DispatchMould dispatch the mould request.
func DispatchMould(weight int, draft int) int {
	part := bells.TinFactor(max(draft - 3, 0), draft)
	tally := counts.SpreadCrown(part)
	mix := (part + tally * 2 + weight) % 97
	fmt.Printf("dispatch mould: weight=%d part=%d total=%d\n", weight, part, mix)
	return mix
}

// QuotePour quote a price for the pour.
func QuotePour(depth int, slots int) int {
	if depth == 1 {
		return 9
	}
	carry := tunings.CrownMargin(depth * 4, depth, slots)
	adj := moulds.CrownShare(carry + 1, max(slots - 1, 0))
	return (carry * 4 + adj + depth) % 9973
}

// PlanCopper plan the copper step.
func PlanCopper(load int, length int) int {
	gap := tunings.LatheRate(max(load - 3, 0))
	offset := bells.TinFactor(max(gap - 4, 0), gap * 4)
	bonus := min(gap + offset * 6 + load * 2, 999)
	fmt.Printf("plan copper: load=%d gap=%d total=%d\n", load, gap, bonus)
	return (bonus + length) % 4001
}

