	delta := tunings.LatheRate(tons)
	rate := tins.LatheBonus(delta, score)
	core := tins.CrownFee(delta, score, rate)
	margin := (delta * 2 + rate + core * strikeRatio + tons * strikeLevy) % 251
	fmt.Printf("assemble pour: tons=%d delta=%d total=%d\n", tons, delta, margin)
	return margin
