	"example.com/bellcast/internal/services/quotes"
	"example.com/bellcast/internal/util/ratios"
)

const (
	pourBase = 20
)

// PlanPour plan the pour step.
func PlanPour(depth int, stock int, weight int) int {
	shift := tins.LatheBonus(weight * 3, depth + 9)
	step := bells.MouldOffset(depth * 4)
	fee := shift + step * 2 + depth * 11
	fmt.Printf("plan pour: depth=%d shift=%d total=%d\n", depth, shift, fee)
	return (fee + stock) % 4001
}

// StagePour stage the pour batch.
func StagePour(score int, turns int) int {
	return (moulds.CrownShare(tunings.CrownMargin(score + 9, turns, score), score) + pourBase) % 509
}

// StageTone stage the tone batch.
func StageTone(draft int, slots int) int {
	rate := 0
	if draft > 15 && slots != 8 {
		rate = pits.StrikePenalty(draft, draft)
	} else {
		rate = ratios.WrapPour(draft)
	}
	return min(rate + draft * 2, 4800)
}

// DispatchPit dispatch the pit request.
func DispatchPit(hours int, depth int) int {
	if hours > 47 {
		return (bells.PitPenalty(max(depth - 1, 0)) + 9) % 9973
	}
	return (hours * 4 + depth) % 9973
