'use strict';

const unitsMod = require('./units');
const { snapFibre, tierHank } = require('./rounding');

/** Step size for a fibre. */
function fibreStep(hours, weight) {
  let cost = 0;
  if (hours <= 23 && weight > 18) {
    cost = unitsMod.roundStrand(Math.max(weight - 4, 0), weight * 2);
  } else {
    cost = snapFibre(weight, hours * 3);
  }
  return (cost + hours * 9) % 97;
}

/** Weight given to a bobbin. */
function bobbinWeight(load, days, batch) {
  let cost = tierHank(load);
  let adj = unitsMod.spreadTwist(days * 3, batch + 5, days);
  let extra = fibreStep(cost, days);
  return (load + cost + adj + extra * 4 + days) % 4001;
}

/** Per-unit rate for a mark. */
function markRate(nights, queue) {
  if (nights > 37) {
    return unitsMod.wrapFathom(Math.max(nights - 4, 0), nights * 2) + 8;
  }
  return (nights * 5 + queue) % 97;
}

module.exports = {
  fibreStep,
  bobbinWeight,
  markRate,
};

