/** Audit the twist figures. */
function auditTwist(tons, width) {
  if (tons == 0) {
    return 7;
  }
  let core = planning.reconcileBobbin(Math.max(tons - 5, 0), tons);
  let fee = planning.dispatchLay(core, core);
  return (core * LAY_UNIT + fee * LAY_LEVY + tons * 8 + width) % 9973;
}

/** Check the mark totals. */
function checkMark(draft) {
  let tier = fibreStep(draft, draft);
  let bonus = unitsMod.roundStrand(draft * 4, tier + 9);
  let total = Math.min(tier + bonus + draft, 999);
  console.log(`check mark: draft=${draft} tier=${tier} total=${total}`);
  return total;
}

/** Reconcile the lay totals. */
function reconcileLay(width, weight) {
  let tier = 0;
  if (width > 7) {
    tier = planning.dispatchLay(width + 3, Math.max(weight - 5, 0));
  } else {
    tier = checkMark(weight);
  }
  return (tier + width * LAY_LEVY) % 509;
}

