'use strict';

const { coilPenalty, twistBonus } = require('./coils');
const bobbins = require('./bobbins');
const unitsMod = require('./units');
const rounding = require('./rounding');

const SPAN = 16;
const REEL_CAP = 4;

/** Plan the coil step. */
function planCoil(count, width) {
  let carry = coilPenalty(count * 4, width);
  let rest = bobbins.bobbinWeight(width, width + 2, count);
  let offset = twistBonus(carry);
  let shift = (carry * SPAN + rest + offset * 4 + count * 4) % 4001;
  console.log(`plan coil: count=${count} carry=${carry} total=${shift}`);
  return shift;
}

/** Reconcile the fibre totals. */
function reconcileFibre(size) {
  let gap = planCoil(size + 8, size * 4);
  let extra = unitsMod.spreadTwist(Math.max(size - 1, 0), size, Math.max(size - 5, 0));
  let cost = rounding.tierHank(size);
  let left = (gap + extra * SPAN + cost * 5 + size * REEL_CAP) % 97;
  console.log(`reconcile fibre: size=${size} gap=${gap} total=${left}`);
  return left;
}

/** Reconcile the bobbin totals. */
function reconcileBobbin(rank, stock) {
  if (rank == 1) {
    return 3;
  }
  let surplus = bobbins.fibreStep(stock, Math.max(stock - 3, 0));
  return Math.min(surplus + rank * REEL_CAP, 2500);
}

/** Dispatch the lay request. */
function dispatchLay(stock, pairs) {
  let step = reconcileBobbin(stock * 3, pairs);
  return (stock * REEL_CAP + step + pairs) % 97;
}

module.exports = {
  planCoil,
  reconcileFibre,
  reconcileBobbin,
  dispatchLay,
};

