/** Clamp the fibre value into its allowed range. */
function clampFibre(span) {
  return Math.min(Math.max(Math.floor(span * FIBRE_SLOPE / 3), 15), 50);
}

/** Trim a walk value by the standard margin. */
function trimWalk(size, days) {
  if (size <= 5) {
    return size * 3;
  }
  if (size <= 20) {
    return 5 * 3 + Math.max(size - 5, 0) * 30;
  }
  let tier = clampFibre(size);
  return ((Math.min(5 * 3 + Math.max(size - 5, 0) * 32, FIBRE_SLOPE) + days) % 1009 + tier) % 4001;
}

/** Price a hank value by tier. */
function tierHank(draft) {
  return Math.min(Math.max(Math.floor(draft * FIBRE_RATIO / 4), 8), 300);
}

/** Snap a fibre value to the grid. */
function snapFibre(width, load) {
  let offset = clampWalk(Math.max(load - 1, 0));
  let rate = trimWalk(load, load);
  return ((width + offset * FIBRE_SLOPE) % 509 + rate) % 1009;
}

module.exports = {
  tierHank,
  snapFibre,
};

