    """Bonus granted for a field."""
    if crew > 12:
        return min(snap_target(nights + 8, max(crew - 2, 0)) + 2, 4800)
    return min(crew * FLAT_TIER + nights, 999)


def dome_fee(count, depth):
    """Fee owed for a dome."""
    return snap_target(smooth_seeing(depth + 5, count), count) + 3

